parameters.jsCode:
// APLICAR DECISIÓN DE CAMPAÑA (IA)
// Recibe la respuesta de Ollama y la alinea con los leads que se enviaron a la IA
// (salida "true" de "¿Campaña Necesita IA?"). La IA solo puede elegir entre las
// campañas permitidas; si responde algo inválido queda en revisión SIN enviar ni fijar campaña.
const sent = $('¿Campaña Necesita IA?').all(0);
const aiItems = $input.all();

if (sent.length !== aiItems.length) {
  throw new Error(
    'Desalineación en la selección de campaña: ' + sent.length + ' lead(s) enviados a la IA vs ' + aiItems.length + ' respuesta(s). Se detiene para no asignar una campaña al lead equivocado.'
  );
}

function plain(v) {
  return String(v === undefined || v === null ? '' : v)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
}
function tryParseJson(raw) {
  if (typeof raw !== 'string') return null;
  let text = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first !== -1 && last > first) text = text.slice(first, last + 1);
  try { return JSON.parse(text); } catch (e) { return null; }
}
function companyKey(row) {
  const id = String(row['ID_Empresa'] || '').trim();
  if (id) return 'id:' + id;
  return 'n:' + plain(row['Empresa']).replace(/\b(sas|s a s|ltda|limitada|sa)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
}

let runMap = {};
try {
  const sd = $getWorkflowStaticData('global');
  const execId = String($execution.id);
  if (!sd.__campaignRun || sd.__campaignRun.exec !== execId) sd.__campaignRun = { exec: execId, map: {} };
  runMap = sd.__campaignRun.map;
} catch (e) { runMap = {}; }

return aiItems.map((ai, i) => {
  const row = { ...(sent[i].json || {}) };
  const allowed = Array.isArray(row._campaignAIAllowed) && row._campaignAIAllowed.length ? row._campaignAIAllowed : ['Unialiados'];
  const fallback = allowed.includes(row._campaignAIDefault) ? row._campaignAIDefault : allowed[0];
  const response = ai.json || {};
  const raw = (response.message && response.message.content) || response.response || '';
  const parsed = tryParseJson(raw);
  const choice = parsed && typeof parsed.campaign === 'string' ? allowed.find((c) => plain(c) === plain(parsed.campaign)) : '';

  let camp;
  let source;
  let reason;
  if (choice) {
    camp = choice;
    source = 'ia';
    const why = parsed && typeof parsed.reason === 'string' ? parsed.reason.replace(/\s+/g, ' ').trim().slice(0, 160) : '';
    reason = 'Elegida por IA entre [' + allowed.join(', ') + ']' + (why ? ': ' + why : '.');
  } else {
    camp = fallback;
    source = 'ia-respaldo';
    const err = response.error ? ' (' + String(typeof response.error === 'string' ? response.error : JSON.stringify(response.error)).slice(0, 120) + ')' : '';
    reason = 'La IA no dio una respuesta válida' + err + '; NO se autoriza envío automático. Campaña sugerida: ' + fallback + '.';
    row._campaignHold = 'La selección de campaña con IA falló. Revisar el lead antes de enviarlo.';
  }

  const key = companyKey(row);
  if (source === 'ia' && !row._campaignHold && !runMap[key]) runMap[key] = camp;

  // Si la IA falló (choice vacío), NO se sobrescribe "Campaña asignada": debe seguir en "Auto"
  // (o lo que tuviera) para que la próxima ejecución vuelva a intentar la selección con la IA,
  // en vez de quedar fijada silenciosamente en la campaña de respaldo (camp).
  const campaignField = choice ? { 'Campaña asignada': camp } : {};

  return {
    json: {
      ...row,
      ...campaignField,
      _campaignAuto: true,
      _campaignNeedsAI: false,
      _campaignDecisionSource: source,
      _campaignDecisionReason: reason,
      _campaignSuggested: camp,
    },
    pairedItem: { item: i },
  };
});

