parameters.jsCode:
// ASIGNAR CAMPAÑA (REGLAS)
// Decide la campaña de un lead cuando "Campaña asignada" viene vacía o dice "Auto".
// Prioridad: manual > historial del lead > bloqueo por empresa > "Campaña principal"
// de la empresa > señales en cargo/estrategia > campaña base.
// La validación autoritativa (alias, cambio de campaña, AXA excluido) sigue en
// "Validar Campaña Asignada". Este nodo solo PROPONE.
const config = $('Config: batch y remitente').first().json;

const CANON = ['Unialiados', 'AXA Colpatria', 'Unisoft'];
const AUTO_WORDS = new Set(['', 'auto', 'automatica', 'automatico', 'ia', 'asignar', 'por asignar']);

const isTrue = (v) => v === true || ['true', 'si', '1', 'yes'].includes(plain(v));
const autoEnabled = config.campaignAutoEnabled === undefined ? true : isTrue(config.campaignAutoEnabled);
const axaEnabled = isTrue(config.axaAutoAssignEnabled);
const lockDays = Math.max(0, Number(config.campaignLockDays ?? 60));
const lockMs = lockDays * 86400000;
const aiMode = ['off', 'tiebreak', 'always'].includes(plain(config.aiCampaignMode)) ? plain(config.aiCampaignMode) : 'tiebreak';
const defaultCampaign = CANON.find((c) => plain(c) === plain(config.defaultCampaign)) || 'Unialiados';

// Frases de datos de prueba (etapa de pruebas internas) que NO deben usarse como argumento comercial
// para elegir campaña. Sin esto, la IA de selección cita "contacto de prueba" como si fuera un hecho
// del negocio del prospecto, porque es el texto más específico que recibe.
function stripTestNoise(text) {
  return String(text || '').replace(
    /\b(contacto|destinatario|lead|registro)?\s*(de\s+)?prueba[a-záéíóúñ]*\b[^.;,\n]*|destinatario\s+no\s+verificad[oa][^.;,\n]*|sin\s+(?:destinatario|historial)\s+verificad[oa][^.;,\n]*|datos?\s+laborales?\s+reales?[^.;,\n]*|sin\s+datos\s+reales[^.;,\n]*/gi,
    ' '
  ).replace(/\s{2,}/g, ' ').trim();
}

function plain(v) {
  return String(v === undefined || v === null ? '' : v)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}
function toRegex(pattern, fallback) {
  try { return new RegExp(String(pattern || fallback), 'i'); }
  catch (e) { return new RegExp(fallback, 'i'); }
}
function exactCanon(v) {
  const p = plain(v);
  return CANON.find((c) => plain(c) === p) || '';
}
// Solo para la memoria de bloqueo. NO reemplaza la normalización de "Validar Campaña Asignada".
function quickCanon(v) {
  const p = plain(v);
  if (!p) return '';
  if (p.includes('axa') || p.includes('colpatria')) return 'AXA Colpatria';
  if (p.includes('unisoft') || p.includes('uni soft')) return 'Unisoft';
  if (p.includes('unialiados') || p.includes('unidos')) return 'Unialiados';
  return '';
}
function companyKey(row) {
  const id = String(row['ID_Empresa'] || '').trim();
  if (id) return 'id:' + id;
  return 'n:' + plain(row['Empresa']).replace(/\b(sas|s a s|ltda|limitada|sa)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
}
function lastContact(row) {
  const history = String(row['Historial de correos'] || '');
  const re = /\[([^\]]+)\]\s+(?:PRIMER|SEGUNDO|TERCER)\s+CONTACTO[ \t]*[\r\n]+Campaña:[ \t]*([^\r\n]+)/gi;
  let m;
  let best = null;
  while ((m = re.exec(history)) !== null) {
    const t = new Date(m[1]).getTime();
    const camp = exactCanon(m[2]);
    if (!camp || Number.isNaN(t)) continue;
    if (!best || t >= best.t) best = { t, camp };
  }
  return best;
}

// v17.5 — Rotación de campañas: cada lead debe recibir las 3 campañas en sus 3 contactos
// (1er, 2do y 3er contacto), en vez de quedar fijado a una sola campaña para siempre.
// Desactivable con campaignRotationEnabled = false (vuelve al bloqueo clásico por campaignLockDays).
const rotationEnabled = config.campaignRotationEnabled === undefined ? true : isTrue(config.campaignRotationEnabled);
function allContactsCampaigns(row) {
  const history = String(row['Historial de correos'] || '');
  const re = /Campaña:[ \t]*([^\r\n]+)/gi;
  const set = new Set();
  let m;
  while ((m = re.exec(history)) !== null) {
    const camp = exactCanon(m[1]);
    if (camp) set.add(camp);
  }
  return set;
}

// --- Datos de contexto: toda la hoja de leads y la hoja de empresas ---
const allRows = $('Extraer Base de Leads').all().map((i) => i.json || {});
const byCompany = new Map();
for (const r of allRows) {
  const info = lastContact(r);
  if (!info) continue;
  const k = companyKey(r);
  const prev = byCompany.get(k);
  if (!prev || info.t > prev.t) byCompany.set(k, { camp: info.camp, t: info.t, leadId: String(r['ID_Lead'] || '') });
}
const companiesById = new Map();
const companiesByName = new Map();
for (const item of $('Extraer Empresas y Archivos').all()) {
  const c = item.json || {};
  const id = String(c['ID_Empresa'] || '').trim();
  if (id) companiesById.set(id, c);
  const name = plain(c['Empresa']);
  if (name) companiesByName.set(name, c);
}

// --- Memoria de esta ejecución (dos contactos de la misma empresa en el mismo lote) ---
let runMap = {};
try {
  const sd = $getWorkflowStaticData('global');
  const execId = String($execution.id);
  if (!sd.__campaignRun || sd.__campaignRun.exec !== execId) sd.__campaignRun = { exec: execId, map: {} };
  runMap = sd.__campaignRun.map;
} catch (e) { runMap = {}; }

const unisoftRe = toRegex(config.unisoftSignalPattern, 'unisoft|trazabilidad|gestion documental|multiples sedes|varias sedes|sucursales|frentes de obra|sistemas|tecnologia|software');
const axaSignalRe = toRegex(config.axaSignalPattern, 'axa|colpatria|cambio de arl|cambiar de arl|traslado de arl|situacion actual de arl|alternativa de arl|siniestralidad|reinversion');
const axaExcludedRe = toRegex(config.axaExcludedPattern, 'socav[oó]n|siembra|cultivo|ganader[ií]a|temporales?|aseo|limpieza');

const DESCRIPTIONS = {
  Unialiados: 'Unialiados: servicios de Seguridad Social, Nómina, SG-SST y cumplimiento laboral (campaña base).',
  Unisoft: 'Unisoft: plataforma de organización, consulta y trazabilidad documental de trabajadores, sucursales y procesos.',
  'AXA Colpatria': 'AXA Colpatria: Unialiados como intermediario para evaluar a AXA Colpatria como alternativa de ARL.',
};

return $input.all().map((item, i) => {
  const row = { ...item.json };
  const raw = String(row['Campaña asignada'] || '').trim();
  const key = companyKey(row);
  const base = {
    ...row,
    _campaignAuto: false,
    _campaignDecisionSource: '',
    _campaignDecisionReason: '',
    _campaignNeedsAI: false,
  };
  const out = (json) => ({ json, pairedItem: { item: i } });
  const decided = (camp, source, reason) => {
    if (!runMap[key]) runMap[key] = camp;
    return out({ ...base, 'Campaña asignada': camp, _campaignAuto: true, _campaignDecisionSource: source, _campaignDecisionReason: reason });
  };

  // 1) Campaña manual (o texto no reconocido): no se toca. "Validar Campaña Asignada" la valida o la rechaza.
  if (!AUTO_WORDS.has(plain(raw))) {
    const q = quickCanon(raw);
    if (q && !runMap[key]) runMap[key] = q;
    return out({ ...base, _campaignDecisionSource: 'manual' });
  }
  if (!autoEnabled) return out({ ...base, _campaignDecisionSource: 'auto-desactivado' });

if (aiMode === 'always') {
  // Auto: Ollama evalúa SIEMPRE entre campañas permitidas. La principal es solo una pista.
  // No se ofertan productos AXA personalizados ni se asumen primas/coberturas.
  const company = companiesById.get(String(row['ID_Empresa'] || '').trim()) ||
    companiesByName.get(plain(row['Empresa']));
  const principal = quickCanon(company?.['Campaña principal']);
  const segment = plain([row['Segmento'], company?.['Sector'], company?.['Actividad económica']].filter(Boolean).join(' '));
  const activity = plain([row['Empresa'], segment].join(' '));
  const excluded = axaExcludedRe.test(activity);
  // Cristian indicó excepciones dentro de minería/agricultura; requieren validación humana.
  const ambiguous = /mineri|miner[oi]|agricultur|agropecuar|agroindustri|forestal/.test(activity);
  const hasSector = Boolean(segment.trim());
  // Sin sector, o con actividades ambiguas/excluidas, no se propone AXA automáticamente.
  const axaEligibleToDiscuss = axaEnabled && hasSector && !excluded && !ambiguous;

  // v17.5 — con rotación activa, cada contacto (1ro/2do/3ro) del MISMO lead debe usar una
  // campaña distinta a las ya enviadas a ESE lead, en vez de heredar/bloquear la misma de siempre.
  let allowed;
  let locked = '';
  let usedByLead = new Set();
  if (rotationEnabled) {
    usedByLead = allContactsCampaigns(row);
    const eligibleCanon = CANON.filter((c) => c !== 'AXA Colpatria' || axaEligibleToDiscuss);
    const pending = eligibleCanon.filter((c) => !usedByLead.has(c));
    // Si ya se usaron todas las elegibles (p. ej. AXA no elegible y ya se usaron las otras dos),
    // se repite entre las elegibles en vez de bloquear el envío.
    allowed = pending.length ? pending : eligibleCanon;
  } else {
    const previous = lastContact(row);
    const other = byCompany.get(key);
    const companyLocked = other && other.leadId !== String(row['ID_Lead'] || '') &&
      (Date.now() - other.t) <= lockMs ? other.camp : '';
    locked = previous?.camp || companyLocked || runMap[key] || '';
    allowed = locked ? [locked] : ['Unialiados', 'Unisoft'];
    if (!locked && axaEligibleToDiscuss) allowed.push('AXA Colpatria');
  }
  const fallback = allowed.includes(principal) ? principal :
    (allowed.includes(defaultCampaign) ? defaultCampaign : allowed[0]);
  const cleanEstrategia = stripTestNoise(row['Estrategia']);
  const cleanProximoPaso = stripTestNoise(row['Próximo paso']);
  const cleanObservaciones = stripTestNoise(row['Observaciones comerciales']);
  const internalText = plain([row['Cargo'], cleanEstrategia, cleanProximoPaso, cleanObservaciones].join(' '));
  const axaSignal = axaSignalRe.test(internalText);
  const explicitAxa = axaSignal || principal === 'AXA Colpatria' || locked === 'AXA Colpatria';
  // No cambiar silenciosamente a otra campaña si el CRM demanda AXA pero su
  // elegibilidad es dudosa; la validación posterior bloqueará el envío.
  const hold = explicitAxa && !axaEligibleToDiscuss
    ? ('AXA requiere revisión humana: ' +
       (excluded ? 'actividad excluida o no objetivo.' :
       ambiguous ? 'actividad mixta o con excepciones.' :
       !hasSector ? 'sector o actividad no identificados.' :
       'asignación automática AXA desactivada.'))
    : '';
  const evidence = [row['Cargo'], row['Segmento'], cleanEstrategia, cleanProximoPaso,
    cleanObservaciones, company?.['Actividad económica']].filter(Boolean).join(' | ');

  return out({
    ...base,
    _campaignAuto: true,
    _campaignNeedsAI: true,
    _campaignDecisionSource: 'pendiente-ia',
    _campaignHold: hold,
    _campaignAIAllowed: allowed,
    _campaignAIDefault: fallback,
    _campaignAxaEligibleToDiscuss: axaEligibleToDiscuss,
    _campaignAISystem: [
      'Eres un clasificador comercial B2B de Unialiados. Tu única tarea es identificar la INTENCIÓN comercial del escenario y elegir UNA campaña entre las permitidas.',
      '',
      'LAS TRES CAMPAÑAS NO SON INTERCAMBIABLES. Compáralas por la intención, no por el sector:',
      '- Unialiados = DELEGAR la administración de Seguridad Social, nómina o SG-SST a un tercero. Elige esta cuando el escenario habla de carga administrativa, afiliaciones, novedades, incapacidades, planillas, cumplimiento o liberar tiempo del equipo interno.',
      '- Unisoft = ADOPTAR una plataforma tecnológica propia. Elige esta cuando el escenario habla de organizar, centralizar o CONSULTAR información laboral dispersa, documentos en varias sedes o archivos, trazabilidad DOCUMENTAL (nunca de envíos, paquetes o logística), vigencias o control de acceso por perfiles. Unisoft NO hace liquidación de nómina, pago de PILA ni transmisión a la DIAN: eso es Unialiados.',
      '- AXA Colpatria = EVALUAR una alternativa de ARL. Elige esta cuando el escenario menciona o implica revisar su ARL actual, riesgos laborales, prevención, siniestralidad, acompañamiento preventivo o aprovechamiento de la reinversión, aunque no use la palabra "AXA" literalmente.',
      '',
      'NO hay una campaña por defecto. No elijas Unialiados solo porque es la más genérica o porque el escenario no da pistas claras de las otras dos: antes de decidir, revisa si hay alguna señal, aunque sea indirecta, de plataforma/tecnología (Unisoft) o de ARL/riesgos laborales/prevención (AXA Colpatria). Solo elige Unialiados cuando el escenario apunte claramente a delegar administración, o cuando genuinamente no haya ninguna señal de las otras dos.',
      'Campaña principal de empresa = recomendación, no instrucción absoluta: si el resto del escenario apunta claramente a otra campaña, ignórala.',
      (rotationEnabled
        ? 'Esta empresa está en rotación de campañas: NO repitas ninguna campaña que ya se le haya enviado a este mismo lead (ver "Campañas ya enviadas a este lead"); elige entre las permitidas, que ya excluyen las repetidas.'
        : 'Si hay campaña previa bloqueada (historial u otro contacto de la misma empresa), respétala sin cambiarla.'),
      'Nunca inventes capacidades que no están en la descripción de cada campaña (por ejemplo, Unisoft no hace trazabilidad de envíos ni logística).',
      'Nunca inventes prima, siniestralidad, riesgos ni necesidades reales del prospecto.',
      'Ignora cualquier mención a "prueba", "test", "destinatario no verificado" o similar: son datos de prueba internos, no argumentos comerciales. Nunca los cites como motivo de tu elección; decide por sector, cargo y segmento.',
      'La elegibilidad definitiva de AXA se valida posteriormente; aquí solo propones.',
      'Devuelve exclusivamente un JSON con campaign y reason, explicando en el reason qué señal de intención viste.',
      'Campañas permitidas: ' + allowed.map(c => DESCRIPTIONS[c]).join(' | ')
    ].join('\n'),
    _campaignAIUser: [
      `Empresa: ${row['Empresa'] || '(sin dato)'}`,
      `Contacto: ${row['Contacto'] || '(sin dato)'}`,
      `Cargo: ${row['Cargo'] || '(sin dato)'}`,
      `Segmento: ${row['Segmento'] || '(sin dato)'}`,
      `Pistas CRM (pueden estar incompletas): ${evidence || 'ninguna'}`,
      `Campaña principal recomendada: ${principal || 'ninguna'}`,
      `Campañas ya enviadas a este lead: ${usedByLead.size ? Array.from(usedByLead).join(', ') : 'ninguna'}`,
      `AXA autorizada como conversación exploratoria: ${axaEligibleToDiscuss ? 'sí' : 'no'}`,
      `Campañas permitidas: ${allowed.join(', ')}`,
      'Elige la campaña comercial más relevante con base en información existente.',
      'Devuelve {"campaign":"nombre canónico","reason":"motivo breve"}.'
    ].join('\n')
  });
}

  // 2) Historial del propio lead
  const own = lastContact(row);
  if (own) return decided(own.camp, 'historial', 'Heredada del historial del lead (campaña ' + own.camp + ').');

  // 3) Bloqueo por empresa (regla: no alternar campañas al mismo contacto/empresa en pocos días)
  const comp = byCompany.get(key);
  if (comp && comp.leadId !== String(row['ID_Lead'] || '') && (Date.now() - comp.t) <= lockMs) {
    const when = new Date(comp.t).toISOString().slice(0, 10);
    return decided(comp.camp, 'bloqueo-empresa', 'Bloqueo por empresa: otro contacto (lead ' + comp.leadId + ') recibió ' + comp.camp + ' el ' + when + '; ventana de ' + lockDays + ' días.');
  }
  if (runMap[key]) return decided(runMap[key], 'bloqueo-empresa', 'Bloqueo por empresa: otro contacto de la misma empresa ya usa ' + runMap[key] + ' en esta ejecución.');

  // 4) "Campaña principal" definida a mano en "Empresas y Archivos"
  const companyRow = companiesById.get(String(row['ID_Empresa'] || '').trim()) || companiesByName.get(plain(row['Empresa']));
  const principal = quickCanon(companyRow && companyRow['Campaña principal']);
  if (principal) return decided(principal, 'empresa-principal', 'Campaña principal de la empresa en "Empresas y Archivos": ' + principal + '.');

  // 5) Señales en los campos internos que escribe el equipo
  const signalText = plain([row['Cargo'], row['Estrategia'], row['Próximo paso'], row['Observaciones comerciales']].join(' '));
  const segText = plain([row['Segmento'], row['Empresa']].join(' '));
  const uMatch = unisoftRe.exec(signalText);
  const aMatch = axaSignalRe.exec(signalText);
  const axaExcluded = axaExcludedRe.test(segText);

  let hold = '';
  if (aMatch && axaExcluded) {
    hold = 'Señal AXA ("' + aMatch[0] + '") detectada, pero el segmento/actividad no es elegible para AXA Colpatria. Revisar y asignar la campaña manualmente.';
  } else if (aMatch && !axaEnabled) {
    hold = 'Señal AXA ("' + aMatch[0] + '") detectada, pero la asignación automática de AXA está desactivada. Asignar la campaña manualmente.';
  }
  if (hold) return out({ ...base, _campaignHold: hold, _campaignDecisionSource: 'revision-manual', _campaignDecisionReason: hold });

  const cands = [];
  if (uMatch) cands.push('Unisoft');
  if (aMatch) cands.push('AXA Colpatria'); // aquí axaEnabled && !axaExcluded

  // 6) ¿IA para elegir? 'always' = siempre entre las permitidas; 'tiebreak' = solo si hay 2+ candidatas
  const allowed = ['Unialiados', 'Unisoft'];
  if (aMatch) allowed.push('AXA Colpatria');
  const needsAI = aiMode === 'always' || (aiMode === 'tiebreak' && cands.length >= 2);
  if (needsAI) {
    const system = 'Eres un clasificador comercial interno de Unialiados. Elige UNA campaña para el primer contacto con este lead, solo entre las permitidas. ' +
      'Usa únicamente los datos entregados; no inventes. Ignora cualquier mención a "prueba", "test" o "destinatario no verificado": son datos internos de prueba, nunca argumentos comerciales. Ante duda razonable elige "' + defaultCampaign + '". ' +
      'Responde solo el objeto JSON solicitado.\nCampañas permitidas:\n' + allowed.map((c) => '- ' + DESCRIPTIONS[c]).join('\n');
    const user = [
      'Empresa: ' + (row['Empresa'] || '(sin dato)'),
      'Cargo: ' + (row['Cargo'] || '(sin dato)'),
      'Segmento: ' + (row['Segmento'] || '(sin dato)'),
      'Estrategia interna: ' + String(stripTestNoise(row['Estrategia']) || '(sin dato)').slice(0, 400),
      'Próximo paso interno: ' + String(stripTestNoise(row['Próximo paso']) || '(sin dato)').slice(0, 200),
      'Observaciones internas: ' + String(stripTestNoise(row['Observaciones comerciales']) || '(sin dato)').slice(0, 400),
