const config = $('Config: batch y remitente').first().json;

const aliases = {
  // Unialiados
  'unialiados': 'Unialiados',
  'unidos y aliados': 'Unialiados',
  'unidos & aliados': 'Unialiados',
  'unidos aliados': 'Unialiados',
  'unidos y aliados de colombia': 'Unialiados',
  'unidos & aliados de colombia': 'Unialiados',
  'unidos aliados de colombia': 'Unialiados',
  'unidos y aliados de colombia sas': 'Unialiados',
  'unidos & aliados de colombia sas': 'Unialiados',

  // AXA Colpatria
  'axa': 'AXA Colpatria',
  'axa colpatria': 'AXA Colpatria',
  'colpatria': 'AXA Colpatria',
  'axa seguros': 'AXA Colpatria',
  'axa arl': 'AXA Colpatria',
  'arl axa': 'AXA Colpatria',
  'arl axa colpatria': 'AXA Colpatria',
  'axa colpatria arl': 'AXA Colpatria',

  // UNISOFT
  'unisoft': 'Unisoft',
  'uni soft': 'Unisoft',
  'unisoft plataforma': 'Unisoft',
  'plataforma unisoft': 'Unisoft',
  'software unisoft': 'Unisoft',
};

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\b(s\.?\s*a\.?\s*s\.?|ltda\.?|limitada)\b/g, ' ')
    .replace(/[.,;:()]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonical(value) {
  return aliases[normalize(value)] || '';
}

function lockedCampaign(value) {
  const history = String(value || '');
  const regex = /^Campaña:\s*(.+)$/gim;

  let match;
  let last = '';

  while ((match = regex.exec(history)) !== null) {
    const normalized = canonical(match[1]);

    // Un historial nuevo siempre registra el nombre canónico.
    // Si un bloque antiguo tiene un alias reconocido, también se normaliza.
    if (normalized) last = normalized;
  }

  return last;
}

// v17.5 — con rotación de campañas activa, un lead puede cambiar de campaña entre
// contactos a propósito (1er/2do/3er contacto = 3 campañas distintas). Esta función
// devuelve TODAS las campañas ya usadas por el lead, no solo la última.
function usedCampaigns(value) {
  const history = String(value || '');
  const regex = /^Campaña:\s*(.+)$/gim;
  const set = new Set();
  let match;
  while ((match = regex.exec(history)) !== null) {
    const normalized = canonical(match[1]);
    if (normalized) set.add(normalized);
  }
  return set;
}

function plain(value) {
  return String(value === undefined || value === null ? '' : value)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
}

// Sectores/actividades que AXA Colpatria no recibe (según Cristian Pardo, 15-oct-2026).
// Editable en "Config: batch y remitente" (axaExcludedPattern). Desactivable con axaBlockExcluded = false.
let axaExcludedRe;
try {
  axaExcludedRe = new RegExp(String(config.axaExcludedPattern || 'socav[oó]n|siembra|cultivo|ganader[ií]a|temporales?|aseo|limpieza'), 'i');
} catch (e) {
  axaExcludedRe = /socav|mineri|minero|agricultur|siembra|ganader|temporal|aseo/i;
}
const axaBlockExcluded = config.axaBlockExcluded === undefined ? true : (config.axaBlockExcluded === true || plain(config.axaBlockExcluded) === 'true');
const rotationEnabled = config.campaignRotationEnabled === undefined ? true : (config.campaignRotationEnabled === true || plain(config.campaignRotationEnabled) === 'true');

return $input.all().map((item, i) => {
  const row = { ...item.json };
  const raw = String(row['Campaña asignada'] || '').trim();
  const assigned = canonical(raw);
  const locked = lockedCampaign(row['Historial de correos']);
  const leadLabel = row['ID_Lead'] || '(sin ID)';

  const used = usedCampaigns(row['Historial de correos']);

  let error = '';

  if (row._campaignHold) {
    // La asignación automática pidió revisión humana (ej.: señal de AXA con AXA automático apagado).
    error = `Lead ${leadLabel} requiere asignación manual de campaña: ${String(row._campaignHold)}`;
  } else if (!assigned) {
    error =
      `Campaña no reconocida para el lead ${leadLabel}: ` +
      `"${raw || '(vacía)'}". Valores permitidos: Unialiados, AXA Colpatria, Unisoft o "Auto".`;
  } else if (!rotationEnabled && locked && locked !== assigned) {
    error =
      `Cambio de campaña bloqueado para el lead ${leadLabel}. ` +
      `Historial: ${locked}; Excel: ${assigned}.`;
  } else if (rotationEnabled && used.size < 3 && used.has(assigned) && assigned === locked) {
    // Con rotación activa SÍ se espera que la campaña cambie entre contactos; lo único que
    // se bloquea es repetir la misma campaña en dos contactos consecutivos mientras aún
    // queden campañas elegibles sin usar.
    error =
      `Repetición de campaña bloqueada para el lead ${leadLabel}: ya se usó ${assigned} en el contacto más reciente. ` +
      `Con rotación activa debe pasar a una campaña distinta antes de repetir.`;
  }

  const finalKey = rotationEnabled ? assigned : (locked || assigned);

  if (!error && finalKey === 'AXA Colpatria' && config.axaCommercialApproved !== true) {
    error = `Lead ${leadLabel}: AXA aún no está autorizada comercialmente. Aprobar con Cristian y activar axaCommercialApproved.`;
  }

  if (!error && finalKey === 'AXA Colpatria' && axaBlockExcluded) {
    const hay = plain([row['Segmento'], row['Empresa']].join(' '));
    const hit = axaExcludedRe.exec(hay);
    if (hit) {
      error =
        `Lead ${leadLabel} no elegible para AXA Colpatria: su segmento/actividad coincide con una exclusión ("${hit[0]}"). ` +
        `Revisar con Lorena/Cristian o cambiar la campaña.`;
    }
  }

  // En Auto, no se envía AXA sin sector suficiente o con actividad ambigua.
  // La transcripción especifica que ciertas actividades agrícolas y mineras
  // tienen excepciones según la actividad real: no extrapolar por IA.
  if (!error && finalKey === 'AXA Colpatria' && row._campaignAuto === true) {
    const hay = plain([row['Segmento'], row['Empresa']].join(' '));
    if (!plain(row['Segmento'])) {
      error = `Lead ${leadLabel}: AXA automática requiere segmento/actividad identificado.`;
    } else if (/mineri|miner[oi]|agricultur|agropecuar|agroindustri|forestal/.test(hay)) {
      error = `Lead ${leadLabel}: actividad AXA con excepciones, requiere validación manual.`;
    } else if (row._campaignAxaEligibleToDiscuss === false) {
      error = `Lead ${leadLabel}: AXA no habilitada para selección automática en este caso.`;
    }
  }

  return {
    json: {
      ...row,
      _campaignValid: !error,
      _campaignKey: finalKey,
      _validationOk: false,
      _validationError: error,
      _canRetry: false,
    },
    pairedItem: { item: i },
  };
});

// v17.0: un envío por buzón dentro del lote y exclusión global por correo.
// El ID del lead sigue siendo único, pero NO autoriza a enviar dos veces al mismo buzón.
const config = $('Config: batch y remitente').first().json;
// Permite repetir buzón entre leads durante pruebas (varios leads de prueba comparten un mismo correo).
// En producción real debe quedar en true para no contactar dos veces al mismo destinatario.
const enforceOneEmailPerMailbox = config.enforceOneEmailPerMailbox !== false;
const items = $input.all();
const seenIds = new Set();
const seenEmails = new Set();
const accepted = [];
const originals = $('Extraer Base de Leads').all().map(i => i.json || {});
const normMail = x => String(x || '').trim().toLowerCase();
const isExcluded = x => ['si','sí','yes','true','1'].includes(String(x || '').trim().toLowerCase());
const optOutEmails = new Set();
const sentEmails = new Map();
for (const r of originals) {
  const mail = normMail(r['Correo']);
  if (!mail) continue;
  if (isExcluded(r['Excluir (Sí/No)']) || /^(?:unsubscribed|desuscrito|no contactar|baja)$/i.test(String(r['Estado'] || '').trim())) optOutEmails.add(mail);
  const count = Math.max(0, Number.parseInt(r['N° de contactos realizados'] || 0, 10) || 0);
  const history = String(r['Historial de correos'] || '');
  // Si algún otro registro del MISMO buzón registra un contacto, evitar una segunda campaña automática.
  if (count > 0 || /\[[^\]]+\]\s+(?:PRIMER|SEGUNDO|TERCER)\s+CONTACTO\b/i.test(history)) {
    if (!sentEmails.has(mail)) sentEmails.set(mail, new Set());
    sentEmails.get(mail).add(String(r['ID_Lead'] ?? '').trim());
  }
}
for (let i = 0; i < items.length; i++) {
  const row = { ...items[i].json };
  const id = String(row['ID_Lead'] ?? '').trim();
  const email = normMail(row['Correo']);
  if (!id || !email) { console.log('LEAD OMITIDO: falta ID o correo', id); continue; }
  if (seenIds.has(id)) { console.log('ID_Lead REPETIDO:', id); continue; }
  seenIds.add(id);
  if (optOutEmails.has(email)) { console.log('BUZÓN EXCLUIDO POR BAJA:', email); continue; }
  if (enforceOneEmailPerMailbox) {
    if (seenEmails.has(email)) { console.log('BUZÓN REPETIDO EN LOTE:', email); continue; }
    const otherLeadSent = [...(sentEmails.get(email) || [])].some(other => other && other !== id);
    if (otherLeadSent) { console.log('BUZÓN YA CONTACTADO EN OTRO LEAD:', email); continue; }
  }
  seenEmails.add(email);
  accepted.push({ json: row, pairedItem: { item: i } });
}
console.log('Leads recibidos:', items.length, '| aceptados:', accepted.length);
return accepted;

const items = $input.all();
