function errorToString(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  try { return JSON.stringify(value); } catch { return String(value); }
}

const sendItems = $input.all();
const originalItems = $('Reconectar después de reservar').all();

if (sendItems.length !== originalItems.length) {
  throw new Error(
    `Desalineación después de SMTP: ${originalItems.length} lead(s) reservados vs ${sendItems.length} respuesta(s) de envío. Se detiene para evitar asociar una respuesta al lead equivocado.`
  );
}

const results = [];

for (let i = 0; i < sendItems.length; i++) {
  const row = { ...(originalItems[i]?.json || {}) };
  const sendResult = sendItems[i]?.json || {};

  if (!row['ID_Lead']) {
    throw new Error(`El item posicional ${i} no contiene ID_Lead después de reconectar la reserva.`);
  }

  const accepted = Array.isArray(sendResult.accepted) ? sendResult.accepted : [];
  const rejected = Array.isArray(sendResult.rejected) ? sendResult.rejected : [];
  const target = String(row.toRecipients || '').trim().toLowerCase();
  const wasAccepted = accepted.some(v => String(v || '').trim().toLowerCase() === target);
  const wasRejected = rejected.some(v => String(v || '').trim().toLowerCase() === target);
  // A single-recipient message may have a messageId without an accepted array, but never
  // treat an explicitly rejected recipient as a successful email.
  const hasConfirmation = wasAccepted || (!accepted.length && !rejected.length && Boolean(sendResult.messageId || sendResult.id));
  const sendOk = !sendResult.error && sendResult.success !== false && !wasRejected && hasConfirmation;
  const sendError = sendOk
    ? ''
    : errorToString(sendResult.error || (wasRejected ? 'SMTP rechazó al destinatario' : 'SMTP no confirmó al destinatario'));

  if (!sendOk) {
    console.log(
      'ENVÍO SMTP FALLÓ:',
      row['ID_Lead'],
      '-',
      row['Empresa'],
      '-',
      sendError
    );
  }

