const config = $('Config: batch y remitente').first().json;
const MAX_HISTORY_CHARS = Math.min(
  30000,
  Math.max(5000, Number(config.maxHistoryChars ?? 28000))
);

function splitHistoryBlocks(value) {
  const text = String(value || '').trim();
  if (!text) return [];

  return text
    .split(/(?=^\[[^\]]+\]\s+)/gm)
    .map(block => block.trim())
    .filter(Boolean);
}

function isContactBlock(block) {
  return /^\[[^\]]+\]\s+(PRIMER|SEGUNDO|TERCER)\s+CONTACTO\b/im.test(
    String(block || '')
  );
}

function compactHistory(value) {
  const blocks = splitHistoryBlocks(value);
  if (!blocks.length) return '';

  // Los contactos reales son fuente de verdad para los topes.
  // Nunca se eliminan por el compactado.
  const contactIndexes = new Set();
  const auxiliaryIndexes = [];

  blocks.forEach((block, index) => {
    if (isContactBlock(block)) contactIndexes.add(index);
    else auxiliaryIndexes.push(index);
  });

  // Conserva únicamente los 3 eventos auxiliares más recientes
  // (errores, cierres u otros), además de TODOS los contactos reales.
  const keptAuxiliary = new Set(auxiliaryIndexes.slice(-3));

  const build = () =>
    blocks
      .filter((_, index) =>
        contactIndexes.has(index) || keptAuxiliary.has(index)
      )
      .join('\n')
      .trim();

  let compacted = build();

  // Si los auxiliares hacen superar el límite, elimina primero
  // los auxiliares más antiguos. Los contactos reales no se tocan.
  while (compacted.length > MAX_HISTORY_CHARS && keptAuxiliary.size > 0) {
    const oldestAuxiliary = [...keptAuxiliary].sort((a, b) => a - b)[0];
    keptAuxiliary.delete(oldestAuxiliary);
    compacted = build();
  }

  // Con el tamaño máximo actual de cada correo, los tres contactos
  // deben caber de sobra. Si una fila histórica antigua excediera el
  // límite solo con contactos, preservamos el encabezado de cada evento
  // y recortamos únicamente el cuerpo de esos bloques.
  if (compacted.length > MAX_HISTORY_CHARS) {
    const contactBlocks = blocks.filter(isContactBlock);
    const budgetPerContact = Math.max(
      1000,
      Math.floor((MAX_HISTORY_CHARS - 500) / Math.max(1, contactBlocks.length))
    );

    compacted = contactBlocks
      .map(block => {
        if (block.length <= budgetPerContact) return block;

        const lines = block.split('\n');
        const preservedHeader = lines.slice(0, 3).join('\n');
        const remainingBudget = Math.max(
          200,
          budgetPerContact - preservedHeader.length - 40
        );
        const body = lines.slice(3).join('\n');

        return `${preservedHeader}\n${body.slice(0, remainingBudget)}\n[CUERPO DEL EVENTO TRUNCADO]`;
      })
      .join('\n')
      .trim();
  }

  return compacted ? compacted + '\n' : '';
}

