function tryParseJson(raw) {
  if (typeof raw !== 'string') return { ok:false, value:null, error:'la respuesta no es texto' };
  let text = raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim();
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first !== -1 && last > first) text = text.slice(first, last + 1);
  try { return { ok:true, value:JSON.parse(text), error:'' }; }
  catch (e) { return { ok:false, value:null, error:e.message }; }
}

function cleanString(value) {
  return typeof value === 'string' ? value.replace(/\s+/g,' ').trim() : '';
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&#039;');
}

function extractEmails(value) {
  const matches = String(value || '').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
  return [...new Map(matches.map(e => [e.toLowerCase(), e])).values()];
}

function safeError(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  try { return JSON.stringify(value); } catch { return String(value); }
}

function buildUnsubscribe(base, leadId) {
  const clean = String(base || '').trim();
  if (!/^https?:\/\//i.test(clean) || /pendiente/i.test(clean)) return '';
  const separator = clean.includes('?') ? '&' : '?';
  return `${clean}${separator}leadId=${encodeURIComponent(String(leadId || ''))}`;
}

// Los datos del cliente vienen en MAYÚSCULAS ("JORGE RAMOS"); el saludo debe quedar "Jorge".
function titleName(value) {
  const s = String(value || '').trim().replace(/\s+/g, ' ');
  if (!s) return '';
  const letters = s.replace(/[^A-Za-zÁÉÍÓÚÜÑáéíóúüñ]/g, '');
  if (!letters) return s;
  const allUpper = letters === letters.toUpperCase();
  const allLower = letters === letters.toLowerCase();
  if (!allUpper && !allLower) return s; // ya tiene mayúsculas y minúsculas mezcladas
  const small = new Set(['de', 'del', 'la', 'las', 'los', 'y', 'e', 'da', 'di']);
  return s.toLowerCase().split(' ').map((w, i) => (i > 0 && small.has(w)) ? w : w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

function firstName(value) {
  return titleName(value).split(/\s+/).filter(Boolean)[0] || '';
}

function greeting() {
  try {
    const hour = Number(new Intl.DateTimeFormat('en-US', { timeZone:'America/Bogota', hour:'2-digit', hour12:false }).format(new Date()));
    return hour >= 12 && hour < 19 ? 'Buenas tardes' : 'Buen día';
  } catch { return 'Buen día'; }
}

function containsPlaceholder(text) {
  const s = String(text || '').toLowerCase();
  return ['[nombre','{nombre','{{nombre','[empresa','{empresa','{{empresa','[contacto','{contacto','{{contacto','<<nombre','<nombre>'].some(m => s.includes(m));
}

// El saludo, nombre y firma son determinísticos. Si el modelo los repite, solicitar otra versión.
function duplicatesPresentation(text, senderName) {
  const s = String(text || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const sender = String(senderName || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  if (sender && s.includes(sender)) return true;
  return /\b(mi nombre es|me llamo|soy (?:laura|parte del equipo comercial)|hago parte del equipo comercial|del equipo comercial de unialiados,? (?:le|me) (?:escribo|contacto))\b/i.test(s);
}

// Evita que Ollama repita la definición general de UNISOFT en CUALQUIER párrafo, no solo en el primero
// (la introducción fija, agregada por el código, ya la cubre una vez).
function repeatsUnisoftIntroduction(paragraphs) {
  // No rechaza usos concretos como "UNISOFT permite consultar vigencias": solo definiciones generales.
  const introducing = /^(?:quisiera presentarle|quiero presentarle|le presento|perm[ií]tame presentarle)/i;
  const redefines = /\bunisoft\b[^.!?]{0,110}\b(?:es|consiste en|se trata de|plataforma|software|herramienta|soluci[oó]n|sistema)\b/i;
  const generalRestatement = /\b(?:unisoft|esta plataforma|el sistema|la plataforma)\b[^.!?]{0,100}\b(?:centraliz\w*|organiz\w*|re[uú]ne|gestion\w*|permite consultar|permite que)\b[^.!?]{0,100}\b(?:informaci[oó]n laboral|documentaci[oó]n laboral|informaci[oó]n de trabajadores|empresas y sucursales|empresas y trabajadores|empresa y trabajador|documentos de trabajadores)\b/i;
  return (paragraphs || []).some(p => {
    const t = String(p || '').trim();
    return introducing.test(t) || redefines.test(t) || generalRestatement.test(t);
  });
}

function unisoftUnsupportedClaim(text) {
  return /\b(liquidaci[oó]n autom[aá]tica de n[oó]mina|transmisi[oó]n autom[aá]tica de n[oó]mina electr[oó]nica|pago autom[aá]tico de (?:la )?pila|integraci[oó]n directa con (?:la )?dian|afiliaciones autom[aá]ticas)\b/i.test(String(text || ''));
}

// ---- v16.6: calidad del contenido ----
function plainText(v) {
  return String(v === undefined || v === null ? '' : v).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
// El modelo a veces envuelve el texto entre comillas o antepone guiones/símbolos a las viñetas.
function stripQuotes(s) {
  return String(s || '').replace(/^[\s"'“”«»‘’]+|[\s"'“”«»‘’]+$/g, '').trim();
}
function stripBullet(s) {
  let t = String(s || '').trim();
  while (/^[•·▪●✓✔►>*\-–—]\s*/.test(t)) t = t.replace(/^[•·▪●✓✔►>*\-–—]\s*/, '');
  return t.trim();
}
function wordCount(s) {
  return String(s || '').split(/\s+/).filter(Boolean).length;
}
// Frases en las que el modelo filtra sus instrucciones o los datos de prueba dentro del correo.
function metaLeak(text) {
  const s = plainText(text);
  return /(sin convertir (?:esto|eso|ello|este)|promesa absoluta|no es una promesa|no constituye (?:una )?promesa|sin (?:presuponer|asumir|suponer) (?:problemas|que (?:su|la|el|usted))|como (?:modelo de lenguaje|asistente de ia|inteligencia artificial)|segun (?:las )?(?:reglas|instrucciones)|prueba sin destinatario|destinatario (?:no )?verificado|contacto de prueba|el prospecto|este lead|campana base|material concreto|dato de respaldo)/.test(s);
}
// Afirmaciones sobre el prospecto o cifras de clientes que no se pueden sustentar.
function assertsAboutLead(text) {
  const s = plainText(text);
  return /\b(?:su empresa|su compania|su organizacion|su area|su equipo)\s+(?:enfrenta|atraviesa|sufre|padece|presenta|tiene)\s+(?:diariamente|constantemente|problemas|dificultades|retrasos|incumplimientos|situaciones)/.test(s)
    || /\b(?:cientos de empresas|mas de \d+ empresas|\d{2,3} empresas atendidas)\b/.test(s)
    || /\bhemos (?:gestionado|asistido|acompanado|resuelto|apoyado|atendido)\b/.test(s);
}
// Apertura formulaica "Con la trayectoria que tiene su empresa..." (salió en 3 de 9 correos de prueba).
function formulaicOpener(first) {
  const s = plainText(first).trim();
  return /^(?:con|dada|dado|teniendo en cuenta|por) (?:la|su|sus) (?:trayectoria|experiencia|solidez|presencia|reputacion)/.test(s)
    || /^(?:su|la) (?:empresa|compania|organizacion)\s+(?:cuenta|tiene|lleva|es una empresa)\b.{0,60}(?:trayectoria|anos|decadas)/.test(s)
    || /^[a-z0-9 .&-]{3,50} es una empresa con mas de \w+ (?:anos|decadas)/.test(s);
}
function shingles(text, n = 11) {
  const w = plainText(text).replace(/[^a-z0-9ñ ]+/g, ' ').split(/\s+/).filter(Boolean);
  const out = new Set();
  for (let i = 0; i + n <= w.length; i++) out.add(w.slice(i, i + n).join(' '));
  return out;
}
// Rechaza el correo si repite 9 palabras seguidas del ejemplo del prompt (copia literal).
// Usar frases del MATERIAL CONCRETO del propio correo es válido (es información verificada): solo cuenta la copia del ejemplo.
function copiesExample(generated, example, allowedText) {
  if (!example) return false;
  const ex = shingles(example);
  const allowed = allowedText ? shingles(allowedText) : new Set();
  for (const s of shingles(generated)) if (ex.has(s) && !allowed.has(s)) return true;
  return false;
}

// Palabras de función del inglés sin equivalente grafico en español (evita falsos positivos con
// préstamos comunes como "email" u "online"). Si aparecen como palabra completa, es mezcla de idioma.
const ENGLISH_LEAK_WORDS = /\b(when|while|where|what|which|who|the|and|with|for|from|please|contact|company|we are|you are|your|about|would|could|should|this is|that is|have|has|their|they|our team|is a|are a|in order to)\b/i;
// El modelo también puede mezclar portugués (visto en producción: "Ajuda" en vez de "ayuda"); estas son
// palabras de función portuguesas sin equivalente gráfico en español, poco probables como préstamo.
const PORTUGUESE_LEAK_WORDS = /\b(ajuda|voc[eê]|n[aã]o|est[aá] |isso|muito|poss[ií]vel|empresa pode|tamb[eé]m|pra|voc[eê]s)\b/i;
// Dos errores reales vistos en producción (lead 4, 19-oct): "Unialiados asumimos..." (falta "En" antes,
// la empresa en 3a persona no puede llevar un verbo conjugado en 1a persona plural) y "emitemos" (no existe;
// es "emitimos", de emitir). No pretende ser un corrector gramatical general, solo estos dos patrones reales.
function grammarSlip(text) {
  const s = String(text || '');
  if (/\bemitemos\b/i.test(s)) return 'usa "emitemos", que no existe (es "emitimos")';
  if (/(?<!\ben\s)\bunialiados\s+(?:asumimos|organizamos|gestionamos|manejamos|registramos|liquidamos|administramos)\b/i.test(s)) {
    return 'dice "Unialiados " seguido de un verbo en nosotros sin el "En" antes (debe ser "En Unialiados ...")';
  }
  return '';
}

function containsEnglishLeak(text) {
  return ENGLISH_LEAK_WORDS.test(String(text || '')) || PORTUGUESE_LEAK_WORDS.test(String(text || ''));
}

function containsPeninsularSpanish(text) {
  return /\b(vosotros|vosotras|estáis|sois|tenéis|queréis|podéis|habéis|necesitáis|vuestro|vuestra|vuestros|vuestras)\b/i.test(String(text || ''));
}

function unsupportedClaim(text) {
  const s = String(text || '');
  return /\b(sabemos que (?:su|sus|ustedes|la empresa)|entendemos que (?:su|sus|ustedes|la empresa)|hemos ayudado a otras?|ayudamos a otras?|otros clientes|otras empresas ya|casos? de éxito|hemos logrado con otras?|empresas como la suya ya)\b/i.test(s);
}

// El primer párrafo del PRIMER contacto no puede abrir con una referencia a algo que no se ha dicho
// (ej. "Así lo entiende la normativa..."). Ojo: \b no funciona después de una letra con tilde (í), por eso el lookahead.
function danglingOpener(paragraphs, stage) {
  if (stage !== 'FIRST' || !paragraphs.length) return false;
  return /^(?:as[ií](?=[\s,;:.]|$)|esto\b|ello\b|lo anterior\b|tal como\b|como se (?:mencion|indic|sabe)|en ese sentido\b|por ello\b|por eso\b)/i.test(paragraphs[0]);
}

function stageViolation(text, stage) {
  if (stage !== 'FIRST') return false;
  return /\b(como hablamos|según nuestra llamada|de acuerdo con nuestra reunión|como acordamos|dando continuidad a nuestra conversación)\b/i.test(String(text || ''));
}

// El remitente no conoce la disponibilidad real del contacto: nunca debe proponer un día,
// fecha u hora concreta para la reunión (pedido explícito, 29-oct-2026). "Lunes a viernes" como
// concepto genérico de días hábiles no cuenta; solo un día/fecha/hora puntual propuesto por el modelo.
const WEEKDAY_RE = /\b(lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo)\b/i;
function inventsMeetingDateOrTime(text) {
  const s = String(text || '');
  if (WEEKDAY_RE.test(s)) return true;
  if (/\b(ma[ñn]ana|pasado ma[ñn]ana|la pr[oó]xima semana|esta semana|el pr[oó]ximo mes)\b/i.test(s)) return true;
  if (/\b([01]?\d)[:.][0-5]\d\s?(am|pm|a\.m\.|p\.m\.)?\b/i.test(s)) return true;
  if (/\ba las?\s+\d{1,2}\b/i.test(s)) return true;
  if (/\b\d{1,2}\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\b/i.test(s)) return true;
  return false;
}
// Un correo con lista de resultados se lee como folleto publicitario, no como un mensaje personal
// (pedido explícito, 29-oct-2026): los párrafos deben ir en prosa, nunca con viñetas/guiones internos.
function paragraphLooksLikeBulletList(paragraphs) {
  return (paragraphs || []).some((p) => /(?:^|\n)\s*[•·▪●✓✔►\-–—]\s+\S/.test(String(p || '')));
}
// El sistema ya agrega el saludo ("Buen día"/"Buenas tardes") antes del primer párrafo; si el modelo
// lo repite dentro del texto, queda un saludo duplicado en el correo final.
function duplicatesGreeting(paragraphs) {
  const first = String((paragraphs && paragraphs[0]) || '').trim();
  return /^(buen\s+d[ií]as?|buenos\s+d[ií]as?|buenas?\s+(tardes|noches))\b/i.test(first);
}

// AXA Colpatria — límites de lo que se puede decir (reunión con Cristian Pardo, 15-oct-2026).
// La cobertura es igual en todas las ARL; los valores agregados dependen de sector, prima y diagnóstico.
const AXA_FORBIDDEN = /\b(comisi[oó]n|mejores? tarifas?|menor(?:es)? tarifas?|descuentos?|ahorr\w*|mejor cobertura|cobertura superior|mayor cobertura|condiciones preferenciales|n[uú]mero uno|l[ií]der(?:es)?|el mejor|la mejor|los [uú]nicos|el [uú]nico|la [uú]nica|helic[oó]ptero|avioneta|garantiz\w*)\b|\d+\s?%/i;
// Compromisos y cotizaciones que una campaña AXA exploratoria nunca debe hacer.
const AXA_SPECIFIC_PROMISES = /\b(?:le (?:garantizamos|asignamos|ofrecemos|entregamos|daremos|incluiremos|instalaremos)|recibir[aá] (?:un m[eé]dico|fisioterapia|un psic[oó]logo|un helic[oó]ptero|vacunas|ambulancia)|tendr[aá] (?:gratis|sin costo|asegurad[oa])|cotizaci[oó]n personalizada|le cotizamos|presupuesto detallado|propuesta econ[oó]mica|por ciento de reinversi[oó]n garantizad[oa])\b/i;
const AXA_OTHER_ARL = /\b(sura|suramericana|positiva|colmena|aurora|equidad|liberty|bol[ií]var|sector p[uú]blico|aseguradoras? p[uú]blicas?|entidades? p[uú]blicas?|estatal(?:es)?)\b/i;
const AXA_NOTE_DEFAULT = 'Los servicios de valor agregado y los beneficios adicionales de AXA Colpatria dependen de la actividad económica y del diagnóstico técnico de cada empresa, y están sujetos a validación.';

const config = $('Config: batch y remitente').first().json;
const SENDER = String(config.senderName || 'Laura Alonso').trim();
const ROLE = 'Equipo Comercial';
const BRAND = 'Unialiados';
const LEGAL = 'UNIDOS & ALIADOS DE COLOMBIA S.A.S.';
const MAX_ATTEMPTS = Math.max(1, Number(config.maxAiAttempts ?? 3));
const MAX_BODY_CHARS = Math.max(500, Number(config.maxBodyChars ?? 2500));
const AXA_NOTE = String(config.axaDisclaimer || AXA_NOTE_DEFAULT).trim();
      const wordTolerance = Math.max(0, Number(config.wordCountTolerance ?? 5));
const aiItems = $input.all();
const results = [];
const preparedAt = new Date().toISOString();

for (let i = 0; i < aiItems.length; i++) {
  const linked = $('Construir Prompt de Correo').itemMatching(i);
  const row = { ...(linked?.json || {}) };
  const attempt = Number(row._aiAttempt) || 1;
  const response = aiItems[i].json || {};
  const raw = response.message?.content || response.response || '';
  const leadLabel = row.ID_Lead || '(sin ID)';

  let validationOk = false;
  let validationRetryable = true;
  let validationError = '';
  let toRecipients = '';
  let emailSubject = '';
  let emailBody = '';
  let emailBodyHtml = '';

  if (response.error && !raw) {
    validationError = `Ollama falló para el lead ${leadLabel}: ${safeError(response.error)}`;
  } else if (!raw) {
    validationError = `Ollama no devolvió contenido para el lead ${leadLabel}.`;
  } else {
    const parsed = tryParseJson(raw);
    if (!parsed.ok || !parsed.value || typeof parsed.value !== 'object' || Array.isArray(parsed.value)) {
      validationError = `JSON inválido de Ollama para el lead ${leadLabel}: ${parsed.error || 'desconocido'}.`;
    } else {
      const obj = parsed.value;
      const keys = Object.keys(obj).sort();
      const exact = JSON.stringify(keys) === JSON.stringify(['bullets','cta','paragraphs','subject']);
      const subject = stripQuotes(cleanString(obj.subject));
      const paragraphs = Array.isArray(obj.paragraphs) ? obj.paragraphs.map((p) => stripQuotes(cleanString(p))).filter(Boolean).slice(0,3) : [];
      const bullets = Array.isArray(obj.bullets) ? obj.bullets.map((b) => stripBullet(stripQuotes(cleanString(b)))).filter(Boolean).slice(0,3) : [];
      const cta = stripQuotes(cleanString(obj.cta));
      const generatedText = [...paragraphs, ...bullets, cta].join('\n');
      const campaign = String(row._campaignKey || '');
      const stage = String(row._stage || 'FIRST');
      const isAxa = campaign === 'AXA Colpatria';
      const totalWords = wordCount([...paragraphs, ...bullets, cta].join(' '));
      const minWords = stage === 'FIRST'
        ? (campaign === 'Unisoft' ? Number(config.minWordsFirstUnisoft ?? 80) : Number(config.minWordsFirst ?? 100))
        : (stage === 'SECOND' ? Number(config.minWordsSecond ?? 60) : Number(config.minWordsThird ?? 40));

      if (!exact) validationError = `La salida de Ollama para ${leadLabel} debe contener únicamente subject, paragraphs, bullets y cta.`;
      else if (!subject) validationError = `Ollama no devolvió subject válido para ${leadLabel}.`;
      else if (subject.length > 100) validationError = `El asunto generado para ${leadLabel} supera 100 caracteres.`;
      else if (paragraphs.length < 1) validationError = `Ollama no devolvió paragraphs válidos para ${leadLabel}.`;
      else if (!cta) validationError = `Ollama no devolvió CTA válido para ${leadLabel}.`;
      else if (generatedText.length > MAX_BODY_CHARS) validationError = `El contenido generado para ${leadLabel} supera ${MAX_BODY_CHARS} caracteres.`;
      else if (containsPlaceholder(subject + ' ' + generatedText)) validationError = `El correo de ${leadLabel} contiene placeholders sin resolver.`;
      else if (duplicatesPresentation(generatedText, SENDER)) validationError = `El correo de ${leadLabel} repite el nombre o la presentación del remitente; n8n ya agrega esa sección.`;
      else if (campaign === 'Unisoft' && stage === 'FIRST' && repeatsUnisoftIntroduction(paragraphs)) validationError = `El correo UNISOFT de ${leadLabel} repite la definición introductoria que n8n agregará automáticamente.`;
      else if (containsPeninsularSpanish(subject + ' ' + generatedText)) validationError = `El correo de ${leadLabel} usa español de España.`;
      else if (containsEnglishLeak(subject + ' ' + generatedText)) validationError = `El correo de ${leadLabel} mezcla palabras en inglés u otro idioma con el español.`;
      else if (grammarSlip(subject + ' ' + generatedText)) validationError = `El correo de ${leadLabel} tiene un error gramatical: ${grammarSlip(subject + ' ' + generatedText)}.`;
      else if (unsupportedClaim(generatedText)) validationError = `El correo de ${leadLabel} contiene una afirmación no sustentada sobre el prospecto o terceros.`;
      else if (stageViolation(generatedText, stage)) validationError = `El primer contacto de ${leadLabel} inventa continuidad previa.`;
      else if (danglingOpener(paragraphs, stage)) validationError = `El primer párrafo de ${leadLabel} abre con una referencia sin antecedente.`;
      else if (inventsMeetingDateOrTime(generatedText)) validationError = `El correo de ${leadLabel} propone un día, fecha u hora específica para la reunión; el remitente no conoce la disponibilidad real del contacto.`;
      else if (duplicatesGreeting(paragraphs)) validationError = `El correo de ${leadLabel} repite el saludo ("Buen día"/"Buenas tardes") dentro del texto; el sistema ya lo agrega antes del primer párrafo.`;
      else if (paragraphLooksLikeBulletList(paragraphs)) validationError = `El correo de ${leadLabel} escribe los párrafos con formato de lista o viñetas; debe ir en prosa corrida, no como folleto.`;
      else if (metaLeak(subject + ' ' + generatedText)) validationError = `El correo de ${leadLabel} filtra instrucciones internas o datos de prueba dentro del texto; escribe solo el mensaje comercial.`;
      else if (formulaicOpener(paragraphs[0])) validationError = `El primer párrafo de ${leadLabel} abre elogiando la trayectoria de la empresa; debe abrir con la situación habitual de su sector o cargo.`;
      else if (assertsAboutLead(generatedText)) validationError = `El correo de ${leadLabel} afirma problemas del prospecto o cifras de clientes que no se pueden sustentar.`;
      else if (copiesExample([...paragraphs, ...bullets].join('\n'), row._exampleText, row._angleText)) validationError = `El correo de ${leadLabel} copia frases del ejemplo; redáctalo con palabras propias.`;
      else if (totalWords < minWords - wordTolerance) validationError = `El correo de ${leadLabel} quedó demasiado breve (${totalWords} palabras; umbral efectivo ${Math.max(0,minWords-wordTolerance)}). Desarrolla la situación habitual, las tareas o funciones concretas y su beneficio práctico.`;
      else if (/\b(adjunto|archivo adjunto|pdf adjunto|propuesta adjunta|portafolio adjunto|encontrará adjunto|le remito)\b/i.test(generatedText) && row._hasRealAttachment !== true) validationError = `El correo de ${leadLabel} menciona un adjunto inexistente.`;
      else if (isAxa && AXA_SPECIFIC_PROMISES.test(subject + ' ' + generatedText)) validationError = `El correo AXA de ${leadLabel} ofrece un beneficio específico o cotización sin validación.`;
      else if (isAxa && AXA_FORBIDDEN.test(subject + ' ' + generatedText)) validationError = `El correo AXA de ${leadLabel} contiene una promesa, cifra, superlativo o información no autorizada.`;
      else if (isAxa && AXA_OTHER_ARL.test(subject + ' ' + generatedText)) validationError = `El correo AXA de ${leadLabel} menciona o compara otra ARL o el sector público.`;
      else if (campaign === 'Unisoft' && /\b(inteligencia artificial|\bapi\b|firma electrónica|biometría|app móvil|aplicación móvil|blockchain|\bocr\b|reconocimiento facial)\b/i.test(generatedText)) validationError = `El correo UNISOFT de ${leadLabel} inventa una capacidad no autorizada.`;
      else if (campaign === 'Unisoft' && unisoftUnsupportedClaim(generatedText)) validationError = `El correo UNISOFT de ${leadLabel} atribuye al software un proceso automático no documentado.`;
      else {
        const emails = extractEmails(row['Correo']);
        if (emails.length !== 1) {
          validationError = `El lead ${leadLabel} debe tener exactamente un correo válido.`;
          validationRetryable = false;
        } else {
          validationOk = true;
          toRecipients = emails[0];
          emailSubject = subject.replace(/[\r\n]+/g,' ').trim();

          const recipient = firstName(row['Contacto']);
          const salutation = `${greeting()}${recipient ? `, ${recipient}` : ''}.`;
          // En AXA Unialiados se presenta con transparencia como intermediario (no como la aseguradora).
          const firstPresentation = stage === 'FIRST'
            ? (isAxa
                ? `Mi nombre es ${SENDER} y hago parte del equipo comercial de ${BRAND}, intermediario aliado de AXA Colpatria en riesgos laborales.`
                : `Mi nombre es ${SENDER} y hago parte del equipo comercial de ${BRAND}.`)
            : '';
          const axaNote = isAxa ? AXA_NOTE : '';
          // El prospecto no conoce UNISOFT: presentación fija sin depender de Ollama.
          const unisoftIntro = campaign === 'Unisoft' && stage === 'FIRST'
            ? 'Quisiera presentarle UNISOFT, la plataforma 360 de Unialiados para la gestión documental del proceso laboral: centraliza la información de trabajadores, empresas y sucursales, y permite que tanto la empresa como cada trabajador consulten su propia documentación, afiliaciones, vigencias e historial de incapacidades y accidentes desde un solo lugar.'
            : '';

          const contentBlocks = [];
          contentBlocks.push(salutation);
          if (firstPresentation) contentBlocks.push(firstPresentation);
          if (unisoftIntro) contentBlocks.push(unisoftIntro);
          contentBlocks.push(...paragraphs);
          if (bullets.length) contentBlocks.push(bullets.map(b => `• ${b}`).join('\n'));
          contentBlocks.push(cta);
          contentBlocks.push(`Cordialmente,\n\n${SENDER}\n${ROLE}\n${BRAND}\n${LEGAL}`);
          if (axaNote) contentBlocks.push(axaNote);

          const unsubscribeUrl = buildUnsubscribe(config.unsubscribeBaseUrl, row['ID_Lead']);
          const footerText = unsubscribeUrl
            ? `Si no desea recibir más comunicaciones, puede darse de baja aquí: ${unsubscribeUrl}`
            : 'Si prefiere no recibir más comunicaciones, responda a este correo indicando “No contactar”.';

          emailBody = `${contentBlocks.join('\n\n')}\n\n---\n${footerText}`;

          const html = [];
          html.push('<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#222222;max-width:640px;margin:0;">');
          html.push(`<p style="margin:0 0 14px 0;">${escapeHtml(salutation)}</p>`);
          if (firstPresentation) html.push(`<p style="margin:0 0 14px 0;">${escapeHtml(firstPresentation)}</p>`);
          if (unisoftIntro) html.push(`<p style="margin:0 0 14px 0;">${escapeHtml(unisoftIntro)}</p>`);
          for (const p of paragraphs) html.push(`<p style="margin:0 0 14px 0;">${escapeHtml(p)}</p>`);
          if (bullets.length) {
            html.push('<ul style="margin:4px 0 14px 20px;padding:0;">');
            bullets.forEach((b, idx) => html.push(`<li style="margin:0 0 ${idx === bullets.length - 1 ? '0' : '5px'} 0;">${escapeHtml(b)}</li>`));
            html.push('</ul>');
          }
          html.push(`<p style="margin:0 0 14px 0;">${escapeHtml(cta)}</p>`);
          html.push('<div style="margin-top:22px;">');
          html.push('<p style="margin:0 0 10px 0;">Cordialmente,</p>');
          html.push(`<p style="margin:0;"><strong>${escapeHtml(SENDER)}</strong><br><span style="color:#555555;">${escapeHtml(ROLE)}</span><br><span style="color:#555555;">${escapeHtml(BRAND)}</span><br><span style="color:#777777;font-size:12px;">${escapeHtml(LEGAL)}</span></p>`);
          html.push('</div>');
          if (axaNote) html.push(`<p style="margin:18px 0 0 0;color:#777777;font-size:11px;line-height:1.45;">${escapeHtml(axaNote)}</p>`);
          const footerHtml = unsubscribeUrl
            ? `Si no desea recibir más comunicaciones, puede darse de baja <a href="${escapeHtml(unsubscribeUrl)}">aquí</a>.`
            : 'Si prefiere no recibir más comunicaciones, responda a este correo indicando &ldquo;No contactar&rdquo;.';
          html.push(`<p style="margin:24px 0 0 0;padding-top:12px;border-top:1px solid #eeeeee;color:#777777;font-size:11px;line-height:1.45;">${footerHtml}</p>`);
          html.push('</div>');
          emailBodyHtml = html.join('');
        }
      }
    }
  }

  const canRetry = !validationOk && validationRetryable && attempt < MAX_ATTEMPTS;

  results.push({
    json: {
      ...row,
      _preparedAt:preparedAt,
      _validationOk:validationOk,
      _validationError:validationOk ? '' : validationError,
      _canRetry:canRetry,
      _aiAttempt:attempt,
      toRecipients,
      _emailSubject:emailSubject,
      _emailBody:emailBody,
      _emailBodyHtml:emailBodyHtml,
    },
    pairedItem:{item:i},
  });
}

return results;

