parameters.jsCode:
const searchItems = $input.all();
const results = [];

function looksAmbiguous(text) {
  const s = String(text || '').toLowerCase();
  if (!s) return false;
  const markers = [
    'different entities', 'multiple entities', 'several entities',
    'three different', 'two different', 'varias empresas', 'diferentes empresas',
    'múltiples empresas', 'multiple companies', 'same name', 'nombre similar',
    'could not determine', 'cannot determine', 'not enough information to identify',
    'no se puede determinar', 'no es posible determinar'
  ];
  return markers.some(m => s.includes(m));
}

for (let i = 0; i < searchItems.length; i++) {
  const linkedLead = $('¿Ya Tiene Investigación Guardada?').itemMatching(i);
  const row = { ...(linkedLead?.json || {}) };
  const search = searchItems[i].json || {};

  let webContext = '';
  if (typeof search.answer === 'string' && search.answer.trim()) {
    webContext = search.answer.trim();
  } else if (Array.isArray(search.results)) {
    webContext = search.results
      .map(r => (r && typeof r.content === 'string') ? r.content.trim() : '')
      .filter(Boolean)
      .join('\n')
      .slice(0, 1600);
  }

  if (!webContext) {
    webContext = String(row['Investigacion de empresa (Tavily)'] || '').trim();
  }

  if (looksAmbiguous(webContext)) {
    row._researchWarning = 'Investigación externa ambigua: aparecen varias entidades con nombres similares. Se omite para evitar personalización incorrecta.';
    webContext = '';
  } else if (search.error && !webContext) {
    row._researchWarning = `Tavily falló: ${typeof search.error === 'string' ? search.error : JSON.stringify(search.error)}`;
  }

  row._webContext = webContext;
  row._researchCacheHit = false;
  if (webContext) row._researchFetchedAt = new Date().toISOString();

  results.push({ json: row, pairedItem: { item: i } });
}

return results;

