const config = $('Config: batch y remitente').first().json;
const TZ = 'America/Bogota';
const STAGE_RULES = {
  'primer contacto': {
    minDays: Number(config.daysToSecond ?? 4),
    stage: 'SECOND',
    action: 'SEND_SECOND',
  },
  'segundo contacto': {
    minDays: Number(config.daysToThird ?? 7),
    stage: 'THIRD',
    action: 'SEND_THIRD',
  },
  'tercer contacto': {
    minDays: Number(config.daysToClose ?? 10),
    stage: null,
    action: 'CLOSE_HOLD',
  },
};

function localDateKey(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ,
    year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
  return `${map.year}-${map.month}-${map.day}`;
}

function dayNumberFromKey(key) {
  if (!key) return null;
  const [y, m, d] = key.split('-').map(Number);
  if (![y, m, d].every(Number.isFinite)) return null;
  return Math.floor(Date.UTC(y, m - 1, d) / 86400000);
}

function parseExcelDate(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) {
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000);
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function daysSince(value, now) {
  if (!value) return null;
  const d = parseExcelDate(value);
  if (!d || Number.isNaN(d.getTime())) return null;
  const a = dayNumberFromKey(localDateKey(now));
  const b = dayNumberFromKey(localDateKey(d));
  if (a === null || b === null) return null;
  return Math.max(0, a - b);
}

const now = new Date();
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const row = { ...items[i].json };
  const estadoRaw = String(row['Estado'] || '').trim();
  const estado = estadoRaw.toLowerCase();
  const contactCount = Number.parseInt(row['N° de contactos realizados'] || 0, 10) || 0;
  const historyHasSentContact = /\[[^\]]+\]\s+(?:PRIMER|SEGUNDO|TERCER)\s+CONTACTO\b/i.test(String(row['Historial de correos'] || ''));

  let action = 'SKIP';
  let stage = null;
  let reason = '';

  const isNeverContacted =
    estado === 'nunca contactado' ||
    (!estado && contactCount === 0 && !row['Último seguimiento']);

  if (isNeverContacted && (contactCount > 0 || historyHasSentContact)) {
    reason = 'INCONSISTENCIA: figura como nunca contactado, pero tiene contactos/historial previos. Revisión manual; no enviar.';
  } else if (isNeverContacted) {
    action = 'SEND_FIRST';
    stage = 'FIRST';
    reason = 'Lead nuevo / nunca contactado';
  } else if (STAGE_RULES[estado]) {
    const rule = STAGE_RULES[estado];
    const referenceDate = row['Último seguimiento'] || row['Fecha de reporte'];
    const days = daysSince(referenceDate, now);

    if (days === null) {
      reason = 'Estado con seguimiento previo, pero sin fecha válida; se omite por seguridad.';
    } else if (days >= rule.minDays) {
      action = rule.action;
      stage = rule.stage;
      reason = `${days} días transcurridos; mínimo requerido ${rule.minDays}.`;
    } else {
      reason = `${days} días transcurridos; mínimo requerido ${rule.minDays}.`;
    }
  } else {
    reason = `Estado no accionable: ${estadoRaw || '(vacío con historial existente)'}`;
  }

  results.push({
    json: { ...row, _action: action, _stage: stage, _eligibilityReason: reason },
    pairedItem: { item: i },
  });
}

return results;

const config = $('Config: batch y remitente').first().json;
const maxPerDay = Math.max(0, Number(config.maxEmailsPerDay ?? 120));
const maxPerMonth = Math.max(0, Number(config.maxEmailsPerMonth ?? 9999));
const maxPerRun = Math.max(0, Number(config.maxLeadsPerRun ?? 120));
const TZ = 'America/Bogota';

function parseExcelDate(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) {
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000);
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function dateParts(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ,
    year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
  return { year: map.year, month: map.month, day: map.day, key: `${map.year}-${map.month}-${map.day}` };
}

const now = new Date();
const nowParts = dateParts(now);
const currentMonthKey = `${nowParts.year}-${nowParts.month}`;
let sentToday = 0;
let sentThisMonth = 0;

// La fuente de verdad para envíos es el historial: solo PRIMER/SEGUNDO/TERCER CONTACTO.
// Cierres y errores NO consumen cupo de correo.
const eventRe = /\[([^\]]+)\]\s+(PRIMER|SEGUNDO|TERCER)\s+CONTACTO\b/gi;
const allRows = $('Extraer Base de Leads').all();

for (const item of allRows) {
  const row = item.json || {};
  const history = String(row['Historial de correos'] || '');
  let parsedEvents = 0;
  let match;
  eventRe.lastIndex = 0;

  while ((match = eventRe.exec(history)) !== null) {
    const d = new Date(match[1]);
    const p = dateParts(d);
    if (!p) continue;
    parsedEvents++;
    if (p.key === nowParts.key) sentToday++;
    if (`${p.year}-${p.month}` === currentMonthKey) sentThisMonth++;
  }

  // Fallback conservador para filas antiguas sin historial estructurado.
  if (parsedEvents === 0) {
    const count = Math.max(0, Number.parseInt(row['N° de contactos realizados'] || 0, 10) || 0);
    if (count > 0) {
      const fallbackDate = parseExcelDate(row['Último seguimiento'] || row['Fecha de reporte'] || '');
      const p = dateParts(fallbackDate);
      if (p) {
        if (p.key === nowParts.key) sentToday += count;
        if (`${p.year}-${p.month}` === currentMonthKey) sentThisMonth += count;
      }
    }
  }
}

const remainingToday = Math.max(0, maxPerDay - sentToday);
const remainingThisMonth = Math.max(0, maxPerMonth - sentThisMonth);
let remainingSendSlots = Math.min(remainingToday, remainingThisMonth);

const items = $input.all();
const selected = [];

for (const item of items) {
  if (selected.length >= maxPerRun) break;
  const action = String(item.json?._action || '');
  const isSend = action === 'SEND_FIRST' || action === 'SEND_SECOND' || action === 'SEND_THIRD';

  if (!isSend) {
    // Cierres/mantenimiento nunca consumen el cupo de correo.
    selected.push(item);
    continue;
  }

  if (remainingSendSlots > 0) {
    selected.push(item);
    remainingSendSlots--;
  }
}

return selected;

const normalize = (value) => String(value || '').trim().toLowerCase();
const priorityWeight = { alta: 0, media: 1, baja: 2 };

const items = $input.all().map((item, index) => ({
  json: {
    ...item.json,
    _priorityWeight: priorityWeight[normalize(item.json['Prioridad'])] ?? 99,
    _originalOrder: index,
  },
  pairedItem: { item: index },
}));

items.sort((a, b) =>
  (a.json._priorityWeight - b.json._priorityWeight) ||
  (a.json._originalOrder - b.json._originalOrder)
);

return items;

